        launch { try { delay(100); log("muffins baked") } finally { log("muffins: finally") } }
    }
    try {
        if (supervised) supervisorScope(bakeAll) else coroutineScope(bakeAll)
        log("scope returned normally")
    } catch (e: BurnedException) {
