class ReminderSender(dispatcher: CoroutineDispatcher = Dispatchers.IO) {
    private val handler = CoroutineExceptionHandler { _, e -> log.warn("reminder failed", e) }

    // SupervisorJob: one failed text doesn't cancel the others or the scope
    private val scope = CoroutineScope(SupervisorJob() + dispatcher + handler)

    fun remind(guest: String): Job =
        scope.launch { texts.send(guest) }       // a root child: failures reach the handler

    fun close() = scope.cancel()
}

